contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address spender, uint256 v1, uint256 v2) public {
        require(spender != address(0));
        bool ok1 = c.approve(spender, v1); if (__ESBMC_reverted()) return;
        bool ok2 = c.approve(spender, v2); if (__ESBMC_reverted()) return;
        assert(ok1 && (c.allowance(address(this), spender) == ((v1 != 0 && v2 != 0) ? v1 : v2)) && (ok2 == !(v1 != 0 && v2 != 0)));
    }
    receive() external payable {}
}

