    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function _run(address spender, uint256 v1, uint256 v2) internal {
        vm.assume(spender != address(0));
        bool ok1;
        try c.approve(spender, v1) returns (bool __r) { ok1 = __r; } catch { return; }
        bool ok2;
        try c.approve(spender, v2) returns (bool __r) { ok2 = __r; } catch { return; }
        assertTrue(ok1 && (c.allowance(address(this), spender) == ((v1 != 0 && v2 != 0) ? v1 : v2)) && (ok2 == !(v1 != 0 && v2 != 0)));
    }

    function testFuzz_run(address spender, uint256 v1, uint256 v2) public {
